package com.nvv.mediadata.data.viewmodelimport android.content.Contextimport androidx.credentials.ClearCredentialStateRequestimport androidx.credentials.CredentialManagerimport androidx.credentials.CustomCredentialimport androidx.credentials.GetCredentialRequestimport androidx.credentials.exceptions.ClearCredentialExceptionimport androidx.credentials.exceptions.GetCredentialExceptionimport androidx.lifecycle.ViewModelimport com.google.firebase.auth.FirebaseAuthimport com.nvv.mediadata.Rimport dagger.hilt.android.lifecycle.HiltViewModelimport javax.inject.Injectimport com.google.android.libraries.identity.googleid.GetGoogleIdOptionimport com.google.android.libraries.identity.googleid.GoogleIdTokenCredentialimport com.google.android.libraries.identity.googleid.GoogleIdTokenCredential.Companion.TYPE_GOOGLE_ID_TOKEN_CREDENTIALimport com.google.firebase.auth.FirebaseUserimport com.google.firebase.auth.GoogleAuthProviderimport com.google.firebase.firestore.FirebaseFirestoreimport timber.log.Timberimport javax.inject.Named@HiltViewModelclass GoogleViewModel @Inject constructor(	@Named("Firebase-Auth")	private val auth: FirebaseAuth,	@Named("Firestore")	private val firestore: FirebaseFirestore) : ViewModel(){	fun getUser() : FirebaseUser? {		return auth.currentUser	}	suspend fun login(context: Context,	                  onSuccess: () -> Unit,	                  onFailed: (String) -> Unit,){		val credentialManager = CredentialManager.create(context)		val googleIdOption: GetGoogleIdOption = GetGoogleIdOption.Builder()			.setFilterByAuthorizedAccounts(false)			.setAutoSelectEnabled(false)			.setServerClientId(context.getString(R.string.web_client_id))			.build()		val request = GetCredentialRequest.Builder()			.addCredentialOption(googleIdOption)			.build()		try {			val result = credentialManager.getCredential(				context = context,				request = request			)			if (result.credential is CustomCredential &&				result.credential.type == TYPE_GOOGLE_ID_TOKEN_CREDENTIAL) {				val googleIdTokenCredential = GoogleIdTokenCredential.createFrom(result.credential.data)				val credential = GoogleAuthProvider.getCredential(googleIdTokenCredential.idToken, null)				auth.signInWithCredential(credential)					.addOnCompleteListener{ task ->						if (task.isSuccessful){							auth.currentUser?.email?.let { email ->								Timber.tag("google login").d(email)								onSuccess()							}						}else{							Timber.tag("google login").e(task.exception)							onFailed(task.exception?.message ?: "Login with Google failed")						}					}			}else {				Timber.tag("google login").d("failed")				onFailed(					"Login with Google failed"				)			}		}catch (e: GetCredentialException){			Timber.tag("google login").e(e)			onFailed(				e.message?:"Login with Google failed"			)		}	}	suspend fun signOut(context: Context){		this.auth.signOut()		val credentialManager = CredentialManager.create(context)		try{			val clearRequest = ClearCredentialStateRequest()			credentialManager.clearCredentialState(clearRequest)		}catch(e: ClearCredentialException){		}	}}